def _stable_node_id(spec: SciencePlacementSpec) -> str:
    raw = "|".join((
        CURRICULUM_VERSION, spec.course_type, spec.level, spec.strand_code,
        spec.standard_code, spec.unit,
    ))
    return SCIENCE_NODE_PREFIX + sha256(raw.encode("utf-8")).hexdigest()[:16]


def science_placement_for(*, key: str, level: str,
                          topic: str) -> CurriculumPlacement:
    """Return approved science placement while preserving legacy identity."""
    spec = SCIENCE_PLACEMENTS[key]
    strand_code = spec.strand_code or "เสริม"
    return CurriculumPlacement(
        CURRICULUM_VERSION if spec.course_type in {BASIC, ADDITIONAL} else "",
        spec.course_type,
        spec.level,
        strand_code,
        SCIENCE_STRANDS[strand_code],
        spec.standard_code,
        spec.indicator_codes,
        spec.unit,
        _stable_node_id(spec),
        spec.mapping_status,
        level,
    )
